#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — Fresh-Flat migration (portfolio-site ticket 13).
#
# Two separate problems, discovered in order: the database was on a former
# teammate's personal Supabase account (access has since been regained, but
# not yet verified as actually working), and — found after that — the site
# itself is hosted on a Vercel account that isn't Newton's either. This
# wizard always ends with a fresh Vercel import into Newton's own account;
# the database stage branches on whether the regained original project
# turns out to be usable. See
# NewtonProfile/.scratch/portfolio-site/issues/13-fresh-flat-redeploy.md.
# ──────────────────────────────────────────────────────────────────────────

# sanitise_project_url VARNAME — strip the two things that have actually gone
# wrong when pasting the Supabase Project URL into this prompt:
#   1. control characters, e.g. the literal 0x16 that Ctrl-V inserts in Git
#      Bash (where Ctrl-V is NOT paste — use right-click or Shift-Insert), and
#   2. a trailing "/rest/v1/", which is what the dashboard's REST endpoint
#      field shows. createClient() appends that itself, so leaving it on
#      produces doubled paths and every query 404s.
sanitise_project_url() {
  local var="$1" value="${!1}" cleaned
  cleaned=$(printf '%s' "$value" | tr -d '[:cntrl:]' | sed -E 's#/+(rest/v1)?/*$##')
  if [[ "$cleaned" != "$value" ]]; then
    warn "cleaned up the pasted URL → $cleaned"
  fi
  printf -v "$var" '%s' "$cleaned"
}

REPO_DIR="/c/Users/sageb/Documents/Projects/Fresh_Flat/FreshFlat"
ENV_FILE="$REPO_DIR/.env"
MIGRATION_FILE="$REPO_DIR/supabase/migrations/20260826160000_initial_schema.sql"
NEW_LIVE_URL=""

# Decide the database path before the banner, so the stage count is right
# either way — this needs an answer before TOTAL_STAGES can be fixed.
printf '\n%sBefore we start: do you already have working Supabase credentials\n' "$BOLD"
printf 'for the ORIGINAL Fresh-Flat project (the one you just regained access\n'
printf 'to), confirmed to actually work?%s\n' "$RESET"
REUSE_DB=false
if confirm "Reuse the original project? (No = provision a brand-new one)"; then
  REUSE_DB=true
fi

if $REUSE_DB; then
  TOTAL_STAGES=4
else
  TOTAL_STAGES=5
fi

banner "Fresh-Flat migration — new Vercel account (+ database)"

# ── Stage: Supabase ─────────────────────────────────────────────────────────
if $REUSE_DB; then
  stage "Supabase — reuse the original project"
  say "Using the regained access to the original project's owner account."
  open_url "https://supabase.com/dashboard/projects"
  step "Log in with the regained access, open the Fresh-Flat project, then"
  step "go to Project Settings → Data API (or 'API' on older dashboards)."
  step "Copy the Project URL."
  ask NEXT_PUBLIC_SUPABASE_URL "Paste the Project URL:"
  sanitise_project_url NEXT_PUBLIC_SUPABASE_URL
  step "Copy the 'anon' / 'public' key from the same page."
  ask_secret NEXT_PUBLIC_SUPABASE_ANON_KEY "Paste the anon public key:"
  step "Copy the 'service_role' / 'secret' key too — treat it like a"
  step "password, it bypasses row security."
  ask_secret SUPABASE_SERVICE_ROLE_KEY "Paste the service_role key:"
  write_env NEXT_PUBLIC_SUPABASE_URL "$NEXT_PUBLIC_SUPABASE_URL"
  write_env NEXT_PUBLIC_SUPABASE_ANON_KEY "$NEXT_PUBLIC_SUPABASE_ANON_KEY"
  write_env SUPABASE_SERVICE_ROLE_KEY "$SUPABASE_SERVICE_ROLE_KEY"
  note "All three written to $ENV_FILE — this file is already gitignored."
  note "No migration needed — the schema already exists on this project."
else
  stage "Supabase — create a new project"
  say "The original project's owner is out of reach, so this is a"
  say "from-scratch rebuild on a project you administer."
  open_url "https://supabase.com/dashboard/projects"
  step "Sign up / log in, then 'New Project'. Name it e.g. 'fresh-flat', set"
  step "a database password (save it), pick any region, and create it."
  step "Once ready, go to Project Settings → Data API (or 'API') and copy"
  step "the Project URL."
  ask NEXT_PUBLIC_SUPABASE_URL "Paste the Project URL:"
  sanitise_project_url NEXT_PUBLIC_SUPABASE_URL
  step "Copy the 'anon' / 'public' key from the same page."
  ask_secret NEXT_PUBLIC_SUPABASE_ANON_KEY "Paste the anon public key:"
  step "Copy the 'service_role' / 'secret' key too — treat it like a"
  step "password, it bypasses row security."
  ask_secret SUPABASE_SERVICE_ROLE_KEY "Paste the service_role key:"
  write_env NEXT_PUBLIC_SUPABASE_URL "$NEXT_PUBLIC_SUPABASE_URL"
  write_env NEXT_PUBLIC_SUPABASE_ANON_KEY "$NEXT_PUBLIC_SUPABASE_ANON_KEY"
  write_env SUPABASE_SERVICE_ROLE_KEY "$SUPABASE_SERVICE_ROLE_KEY"
  note "All three written to $ENV_FILE — this file is already gitignored."

  stage "Apply the schema to the new project"
  say "No schema was ever committed for the original project, so this is"
  say "reconstructed from the application code — 6 tables plus the foreign"
  say "keys PostgREST needs for the app's embedded selects to work."
  say "Full file: $MIGRATION_FILE"
  open_url "https://supabase.com/dashboard/project/_/sql/new"
  step "Open $MIGRATION_FILE in your own editor, copy its entire contents,"
  step "paste into the SQL Editor, and click 'Run'."
  step "You should see 'Success. No rows returned.' — if it errors, stop"
  step "and report the exact error rather than retrying blindly; a partial"
  step "apply can leave some tables created and others not."
  confirm "Did the migration run successfully with no errors?" || {
    SKIPPED+=("apply $MIGRATION_FILE via the Supabase SQL Editor")
    warn "skipped — nothing downstream will work until this is applied."
  }
fi

# ── Stage: OpenRouter ───────────────────────────────────────────────────────
stage "OpenRouter — API key for recipe generation"
say "model/recipe.js generates recipes through OpenRouter's free tier, not"
say "OpenAI directly — the original OpenAI key belonged to the same"
say "inaccessible account as the Vercel project, and free models cost"
say "nothing to run. Same arrangement Note-Pilot uses."
open_url "https://openrouter.ai/keys"
step "If you already have an OpenRouter key (Note-Pilot uses one), reuse it."
step "Otherwise click 'Create Key', name it (e.g. 'fresh-flat'), and copy it"
step "— OpenRouter only shows it once."
ask_secret OPENROUTER_API_KEY "Paste the OpenRouter API key (OPENROUTER_API_KEY):"
write_env OPENROUTER_API_KEY "$OPENROUTER_API_KEY"
note "Free models are capped per day on a zero-balance account. Adding a"
note "small amount of credit to OpenRouter raises that ceiling considerably"
note "without changing which models are used."

# ── Stage: Vercel — fresh import into Newton's own account ─────────────────
stage "Vercel — import into your own account"
say "The current fresh-flat.vercel.app is on a Vercel account that isn't"
say "Newton's — importing straight from GitHub into your own account gives"
say "you a project you actually control, with auto-deploys on every push."
say "The live URL WILL change — the fresh-flat.vercel.app subdomain stays"
say "claimed by the other account regardless of what happens to it."
open_url "https://vercel.com/new"
step "Log in, then 'Import Git Repository' and pick"
step "NewtonSythong/Fresh-Flat (github.com/NewtonSythong/Fresh-Flat)."
step "Framework preset auto-detects as Next.js — leave build settings as-is."
step "Before clicking Deploy, expand 'Environment Variables' and add all"
step "four below (paste the same values you just captured):"
note "  NEXT_PUBLIC_SUPABASE_URL      = ${NEXT_PUBLIC_SUPABASE_URL:0:30}...(hidden)"
note "  NEXT_PUBLIC_SUPABASE_ANON_KEY = ...(hidden)"
note "  SUPABASE_SERVICE_ROLE_KEY     = ...(hidden)"
note "  OPENROUTER_API_KEY            = ...(hidden)"
step "Click Deploy and wait for the build to finish."
ask NEW_LIVE_URL "Paste the live production URL Vercel gives you:"
note "Once confirmed working in the next stage, this URL needs to replace"
note "fresh-flat.vercel.app in two places: this repo's own README, and"
note "NewtonProfile's src/content/projects/fresh-flat.md liveDemoUrl field."

# ── Stage: verify ────────────────────────────────────────────────────────────
stage "Verify the new deployment"
if [[ -n "$NEW_LIVE_URL" ]]; then
  open_url "$NEW_LIVE_URL"
fi
step "Sign up for a new account if using the fresh database (nothing"
step "carries over from a brand-new project). If reusing the original"
step "project, sign in with an existing account instead."
step "Create a flat, add a pantry ingredient, generate an AI recipe from"
step "it, and save the recipe."
if ! confirm "Did signup/login, the flat, the pantry ingredient, and the AI recipe all work?"; then
  warn "If auth failed: double-check the three Supabase env vars in Vercel"
  warn "match the project you intended, and that they're scoped to"
  warn "Production."
  warn "If recipe generation failed: check OPENROUTER_API_KEY the same way,"
  warn "and confirm the free-model daily allowance isn't exhausted at"
  warn "openrouter.ai/activity."
  SKIPPED+=("confirm full signup → flat → ingredient → recipe flow on the new deployment")
fi
# ──────────────────────────────────────────────────────────────────────────

finish

if [[ -n "$NEW_LIVE_URL" ]]; then
  printf '  %sNew live URL:%s %s\n' "$BOLD" "$RESET" "$NEW_LIVE_URL"
  printf '  %sRemember:%s update the README and NewtonProfile'"'"'s fresh-flat.md\n\n' "$BOLD" "$RESET"
fi
